svg.script:
//
(function() {
  const steps = [
    { id: 1, color: 'var(--c-passo1)', highlightId: 'p15-highlight-1' },
    { id: 2, color: 'var(--c-passo2)', highlightId: 'p15-highlight-2' },
    { id: 3, color: 'var(--c-passo3)', highlightId: 'p15-highlight-3' },
    { id: 4, color: 'var(--c-alzheimer)', highlightId: 'p15-highlight-4' }
  ];

  function setStep(stepNum) {
    for (let i = 1; i <= 4; i++) {
      // Reset botões
      const btn = document.getElementById('p15-btn-' + i);
      if (btn) btn.classList.remove('active');

      // Reset painéis de detalhes
      const detail = document.getElementById('p15-detail-' + i);
      if (detail) {
        detail.setAttribute('opacity', '0');
        detail.style.pointerEvents = 'none';
      }

      // Reset destaques no cérebro
      const highlight = document.getElementById('p15-highlight-' + i);
      if (highlight) {
        highlight.classList.remove('active');
        highlight.style.stroke = 'var(--c-brain-stroke)';
      }

      // Reset conexões lógica-física
      const conn = document.getElementById('p15-conn-' + i);
      if (conn) {
        conn.classList.remove('active');
        conn.style.stroke = 'var(--border-color)';
      }
    }

    // Ativar botão selecionado
    const activeBtn = document.getElementById('p15-btn-' + stepNum);
    if (activeBtn) activeBtn.classList.add('active');

    // Ativar detalhes selecionados
    const activeDetail = document.getElementById('p15-detail-' + stepNum);
    if (activeDetail) {
      activeDetail.setAttribute('opacity', '1');
      activeDetail.style.pointerEvents = 'all';
    }

    // Ativar conexões físicas e fluxo
    for (let i = 1; i <= 3; i++) {
      const arrow = document.getElementById('p15-arrow-' + i);
      if (arrow) {
        if (i < stepNum) {
          arrow.classList.add('active');
          arrow.style.stroke = steps[i - 1].color;
        } else {
          arrow.classList.remove('active');
          arrow.style.stroke = 'var(--border-color)';
        }
      }
    }

    // Ativar conexão correspondente com o cérebro
    const activeConn = document.getElementById('p15-conn-' + stepNum);
    if (activeConn) {
      activeConn.classList.add('active');
      activeConn.style.stroke = steps[stepNum - 1].color;
    }

    // Comportamentos específicos para o Passo 4 (Alzheimer e Hipocampo)
    const hipo = document.getElementById('p15-hipocampo-shape');
    const ring1 = document.getElementById('p15-alert-ring-1');
    const ring2 = document.getElementById('p15-alert-ring-2');
    const zoomGroup = document.getElementById('p15-zoom-group');

    if (stepNum === 4) {
      if (hipo) {
        hipo.style.stroke = 'var(--c-alzheimer)';
        hipo.style.strokeWidth = '6px';
        hipo.style.opacity = '1';
      }
      if (ring1) ring1.style.animation = 'p15-alert-pulse 1.8s infinite ease-out';
      if (ring2) ring2.style.animation = 'p15-alert-pulse 1.8s infinite ease-out 0.9s';
      if (zoomGroup) zoomGroup.setAttribute('opacity', '1');
    } else {
      if (hipo) {
        hipo.style.stroke = 'var(--c-brain-stroke)';
        hipo.style.strokeWidth = '5px';
        hipo.style.opacity = '0.6';
      }
      if (ring1) ring1.style.animation = 'none';
      if (ring2) ring2.style.animation = 'none';
      if (zoomGroup) zoomGroup.setAttribute('opacity', '0.3');

      // Destaque do córtex correspondente
      const highlight = document.getElementById('p15-highlight-' + stepNum);
      if (highlight) {
        highlight.classList.add('active');
        highlight.style.stroke = steps[stepNum - 1].color;
      }
    }
  }

  function init() {
    setStep(1);
    for (let i = 1; i <= 4; i++) {
      const btn = document.getElementById('p15-btn-' + i);
      if (btn) {
        btn.addEventListener('click', function() { setStep(i); });
        btn.addEventListener('keydown', function(e) {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            setStep(i);
          }
        });
      }
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
//
